using UnityEngine;

/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator. Locomotion is now a
/// velocity blend tree: this just pushes VelocityX/Y/Z (Rigidbody velocity) plus Speed and
/// IsGrounded; the tree owns direction/clip selection. Also owns the wrench swing phase
/// (windup freeze / release scale on animator.speed) and exposes the IPlayerVisual surface
/// (VisualCenter, attack/charge) for the combat & interaction controllers.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class FlynnAnimationDriver : MonoBehaviour, IPlayerVisual
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private Camera _camera;
    [Tooltip("Assign the child Visual GameObject that holds the SpriteRenderer. Only this object will billboard — the physics root stays unrotated.")]
    [SerializeField] private Transform _visualRoot;
    [SerializeField, Range(0.1f, 5f)] private float _visualScale = 1f;

    [Header("Direction views")]
    [Tooltip("Direction view GameObjects under New_Visual. Auto-found by name at Awake if left empty.")]
    [SerializeField] private GameObject _viewFront;
    [SerializeField] private GameObject _viewBack;
    [SerializeField] private GameObject _viewSide;
    [SerializeField] private GameObject _viewLeftBack;
    [SerializeField] private GameObject _viewLeftDown;

    [Header("Facing (sprite flip)")]
    [Tooltip("SpriteRenderer to flip. Auto-found on _visualRoot at Awake if left empty.")]
    [SerializeField] private SpriteRenderer _sprite;
    [Tooltip("Min horizontal speed before facing updates. Below this the last facing is held (no flip flicker when idling).")]
    [SerializeField, Range(0f, 1f)] private float _faceDeadzone = 0.05f;

    [Header("Petal (procedural)")]
    [Tooltip("The single petal transform, reparented directly under New_Visual.")]
    [SerializeField] private Transform _petal;
    [Tooltip("How fast the bounce oscillation runs (cycles per second).")]
    [SerializeField, Range(1f, 20f)] private float _petalBounceSpeed = 8f;
    [Tooltip("Max scale-Y added to the petal at full speed (pivot is on the bottom).")]
    [SerializeField, Range(0f, 0.5f)] private float _petalBounceAmplitude = 0.15f;
    [Tooltip("Max Z-rotation degrees the petal leans towards movement direction.")]
    [SerializeField, Range(0f, 45f)] private float _petalMaxLeanDeg = 20f;
    [Tooltip("How quickly the petal follows the target lean angle (higher = snappier).")]
    [SerializeField, Range(1f, 30f)] private float _petalLeanLerpSpeed = 8f;
    [Tooltip("Max lean angle clamped so the petal never goes fully sideways (degrees).")]
    [SerializeField, Range(0f, 90f)] private float _petalSidewaysClampDeg = 10f;

    [Header("Head bob (procedural)")]
    [Tooltip("Bob oscillation speed (cycles per second at full run speed).")]
    [SerializeField, Range(1f, 20f)] private float _headBobSpeed = 11f;
    [Tooltip("Max vertical offset (world units) at full speed.")]
    [SerializeField, Range(0f, 0.15f)] private float _headBobHeight = 0.04f;
    [Tooltip("Max horizontal sway offset (world units) — creates the figure-8 feel.")]
    [SerializeField, Range(0f, 0.1f)] private float _headBobSway = 0.015f;
    [Tooltip("Max Z-rotation wiggle (degrees) at full speed.")]
    [SerializeField, Range(0f, 15f)] private float _headBobTiltDeg = 5f;

    [Header("Limb walk cycle (procedural)")]
    [Tooltip("Walk cycle speed (cycles per second at full run). Synced with head bob by default.")]
    [SerializeField, Range(1f, 20f)] private float _limbCycleSpeed = 11f;
    [Tooltip("Max rotation degrees for feet during swing.")]
    [SerializeField, Range(0f, 45f)] private float _footTiltDeg = 25f;
    [Tooltip("Max rotation degrees for arms during swing. Arms swing opposite to same-side foot.")]
    [SerializeField, Range(0f, 45f)] private float _armTiltDeg = 20f;

    [Header("Visual Center (for throw origin & aim reticle)")]
    [Tooltip("Half the sprite's visible height in world units. Used to compute the billboard's visual centre for camera-corrected spawn/reticle positions.")]
    [SerializeField, Range(0f, 3f)] private float _spriteHalfHeight = 0.5f;

    /// <summary>
    /// World-space centre of the billboarded sprite, accounting for camera tilt.
    /// Because the billboard's up = camera.up (not world up), the visual centre
    /// shifts horizontally toward the viewer on a tilted perspective camera.
    /// Use this for spawn points and any indicator that should appear to originate
    /// from the sprite rather than from the physics root (feet position).
    /// </summary>
    public Vector3 VisualCenter =>
        _visualRoot != null
            ? _visualRoot.position + _visualRoot.up * _spriteHalfHeight
            : transform.position;

    /// <summary>
    /// XZ projection of VisualCenter at the character's foot Y.
    /// Use this for ground-plane indicators (aim reticle root, shadow) so they
    /// appear centred under the sprite rather than under the physics root.
    /// </summary>
    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    private Animator _animator;

    // Last pressed XZ facing direction, held while idle so the blend tree doesn't snap back to
    // the front/Down pose on release. Starts facing front (Down = -Z).
    private Vector2 _lastFacingXZ = new Vector2(0f, -1f);

    // ── Swing (wrench) phase ────────────────────────────────────────────────────
    // The charge windup freezes the attack clip on frame 0; the release plays it at a
    // charge-scaled speed. These own animator.speed while active so the locomotion speed
    // logic in Update doesn't stomp the freeze/scale.
    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private int _swingIndex;
    private float _attackSpeed = 1f;
    private bool _releaseSeen; // saw the attack state begin after a release (Play settles a frame late)

    private const float AttackFps = 12f; // matches FlynnAnimationSetup.Fps — used to map charge → windup frame
    private const int WindupStartFrame = 1;
    private const int WindupEndFrame   = 5;

    // attackIndex → last-frame index of that attack clip (length*frameRate). Cached at Awake so
    // the windup scrub is exact and never depends on a fragile per-frame state-length read.
    private readonly System.Collections.Generic.Dictionary<int, float> _attackLastFrame
        = new System.Collections.Generic.Dictionary<int, float>();

    // Animator AttackIndex (1-4) → attack state name. Matches FlynnAnimationSetup.
    private static string AttackStateName(int animIndex) => animIndex switch
    {
        1 => "Attack_Pick",
        2 => "Attack_Axe",
        3 => "Attack_Hammer",
        _ => "Attack_Wrench",
    };

    private static readonly int SpeedHash       = Animator.StringToHash("Speed");
    private static readonly int IsGroundedHash  = Animator.StringToHash("IsGrounded");
    private static readonly int AttackHash      = Animator.StringToHash("Attack");
    private static readonly int AttackIndexHash = Animator.StringToHash("AttackIndex");

    private static readonly int xVelocityHash = Animator.StringToHash("VelocityX");
    private static readonly int yVelocityHash = Animator.StringToHash("VelocityY");
    private static readonly int zVelocityHash = Animator.StringToHash("VelocityZ");

    // ── Public API ────────────────────────────────────────────────────────────

    /// <summary>
    /// Fires the correct attack animation. animIndex: 1=pick 2=axe 3=hammer 4=wrench.
    /// Called by the wrench controllers; safe to call from any other system.
    ///
    /// Guard: discards the request while any attack state is already active.
    /// Attack states must carry the "Attack" tag in the Animator Controller for this
    /// guard to work. Without it, the Any State trigger queues up and double-fires
    /// when the animation exits back to idle.
    /// </summary>
    public void TriggerAttack(int animIndex)
    {
        if (_animator == null) return;
        if (IsAttacking) return;
        _animator.SetInteger(AttackIndexHash, animIndex);
        _animator.SetTrigger(AttackHash);
    }

    /// <summary>
    /// Enter the swing windup: jump the matching attack clip to its start frame and pause it.
    /// Bypasses the AnyState "Attack" trigger (so it never double-fires); the release resumes
    /// the same state from wherever the windup paused. Pass the tool's Animator AttackIndex (1-4).
    /// </summary>
    public void BeginChargePose(int animIndex)
    {
        if (_animator == null) return;
        _swingPhase = SwingPhase.Charging;
        _swingIndex = animIndex;
        _animator.Play(AttackStateName(animIndex), 0, 0f);
        _animator.speed = 0f; // paused; UpdateChargePose drives the frame from charge
    }

    /// <summary>
    /// Drive the (paused) windup pose: the clip scrubs from frame 1 → 5 as <paramref name="charge01"/>
    /// goes 0 → 1 and holds at frame 5, so the buildup visibly winds up. Also live-swaps the tool.
    /// </summary>
    public void UpdateChargePose(int animIndex, float charge01)
    {
        return; // TODO
        if (_animator == null || _swingPhase != SwingPhase.Charging) return;
        _swingIndex = animIndex;
        _animator.Play(AttackStateName(animIndex), 0, WindupNormalizedTime(animIndex, charge01));
        _animator.speed = 0f; // paused at the scrubbed frame
    }

    /// <summary>
    /// Charge fraction → clip normalizedTime sitting on a discrete windup frame. Charge 0→1 steps
    /// the displayed frame 1,2,3,4,5 (rounded), holding on frame 5 at full charge.
    /// </summary>
    private float WindupNormalizedTime(int animIndex, float charge01)
    {
        // Last-frame index of this clip (cached). Fallback to a live read if not cached yet.
        if (!_attackLastFrame.TryGetValue(animIndex, out float lastFrame))
        {
            lastFrame = _animator.GetCurrentAnimatorStateInfo(0).length * AttackFps;
            if (lastFrame < 1f) return 0f;
        }
        int frame = Mathf.RoundToInt(Mathf.Lerp(WindupStartFrame, WindupEndFrame, Mathf.Clamp01(charge01)));
        return Mathf.Clamp01(frame / lastFrame);
    }

    /// <summary>
    /// Release the swing: play the attack clip from frame 0 at <paramref name="animSpeed"/>
    /// (lower = heavier/slower). Hands control back to locomotion when the clip exits.
    /// </summary>
    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        if (_animator == null) return;
        if (animIndex != _swingIndex || _swingPhase != SwingPhase.Charging)
        {
            _swingIndex = animIndex;
            _animator.Play(AttackStateName(animIndex), 0, 0f);
        }
        _attackSpeed = Mathf.Max(0.05f, animSpeed);
        _swingPhase = SwingPhase.Releasing;
        _releaseSeen = false;
    }

    /// <summary>Abort a windup (e.g. wrench unequipped / throw started) and return to idle.</summary>
    public void CancelSwing()
    {
        if (_animator == null) { _swingPhase = SwingPhase.None; return; }
        _swingPhase = SwingPhase.None;
        _animator.speed = 1f;
        _animator.Play("Idle_Front", 0, 0f);
    }

    /// <summary>True while the animator is in (or blending into) an attack state.</summary>
    public bool IsAttacking =>
        _animator != null &&
        (_animator.GetCurrentAnimatorStateInfo(0).IsTag("Attack") ||
         (_animator.IsInTransition(0) && _animator.GetNextAnimatorStateInfo(0).IsTag("Attack")));

    /// <summary>
    /// No-op. Facing is now driven by the velocity blend tree (VelocityX/Y/Z), so explicit
    /// orientation is no longer needed. Kept to satisfy <see cref="IPlayerVisual"/>; the
    /// combat/interaction controllers still call it but the blend tree owns facing.
    /// </summary>
    public void FaceWorldDirection(Vector3 worldDir) { }

    private int _lastSector = 6; // default: front/south

    /// <summary>
    /// Switches the active direction view and flips the sprite based on the 8-direction
    /// facing sector. Only one view is active at a time; the rest are deactivated.
    /// Right/UR/DR flip their respective view by setting localScale.x = -1.
    /// </summary>
    private void UpdateDirectionView(Vector3 velocity)
    {
        Vector2 dir = new Vector2(velocity.x, velocity.z);
        if (dir.sqrMagnitude >= _faceDeadzone * _faceDeadzone)
        {
            // 0=E 1=NE 2=N 3=NW 4=W 5=SW 6=S 7=SE  (atan2: x=right, z=up/away)
            float ang = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
            _lastSector = ((Mathf.RoundToInt(ang / 45f) % 8) + 8) % 8;
        }

        // Deactivate all views
        SetViewActive(_viewFront, false);
        SetViewActive(_viewBack, false);
        SetViewActive(_viewSide, false);
        SetViewActive(_viewLeftBack, false);
        SetViewActive(_viewLeftDown, false);

        // Activate the correct view with appropriate flip
        switch (_lastSector)
        {
            case 0: ActivateView(_viewSide, flipX: true);  break;      // E  Right
            case 1: ActivateView(_viewLeftBack, flipX: true); break;    // NE UR
            case 2: ActivateView(_viewBack, flipX: false); break;       // N  Back
            case 3: ActivateView(_viewLeftBack, flipX: false); break;   // NW UL
            case 4: ActivateView(_viewSide, flipX: false); break;       // W  Left
            case 5: ActivateView(_viewLeftDown, flipX: false); break;   // SW DL
            case 6: ActivateView(_viewFront, flipX: false); break;      // S  Front
            case 7: ActivateView(_viewLeftDown, flipX: true); break;     // SE DR
        }
    }

    private static void SetViewActive(GameObject view, bool active)
    {
        if (view != null) view.SetActive(active);
    }

    private static void ActivateView(GameObject view, bool flipX)
    {
        if (view == null) return;
        view.SetActive(true);
        var s = view.transform.localScale;
        s.x = flipX ? -1f : 1f;
        view.transform.localScale = s;
    }

    // ── Petal procedural animation ─────────────────────────────────────────────

    private float _petalBaseScaleY;
    private float _petalCurrentLean;
    private bool _petalInitialized;

    private void InitPetal()
    {
        if (_petal == null || _petalInitialized) return;
        _petalBaseScaleY = _petal.localScale.y;
        _petalCurrentLean = 0f;
        _petalInitialized = true;
    }

    /// <summary>
    /// Drives the petal's bounce (scale-Y) and lean (Z-rotation towards movement).
    /// Lean is clamped so the petal never tilts fully sideways; the sideways component
    /// is damped while forward/back lean responds fully.
    /// </summary>
    private void UpdatePetal(Vector2 facingXZ, float speed)
    {
        if (_petal == null) return;
        InitPetal();

        // ── Bounce: scale-Y sine wave driven by speed ──
        float bounce = Mathf.Sin(Time.time * _petalBounceSpeed) * _petalBounceAmplitude * Mathf.Clamp01(speed);
        var scale = _petal.localScale;
        scale.y = _petalBaseScaleY + bounce;
        _petal.localScale = scale;

        // ── Lean: Z-rotation towards movement direction ──
        // Decompose facing into forward (Z) and sideways (X) components.
        // Forward lean is allowed fully; sideways lean is clamped to _petalSidewaysClampDeg.
        float forwardLean = -facingXZ.y * _petalMaxLeanDeg;          // N/S → Z rotation
        float sidewaysLean = facingXZ.x * _petalMaxLeanDeg;          // E/W → Z rotation (would go fully sideways)
        sidewaysLean = Mathf.Clamp(sidewaysLean, -_petalSidewaysClampDeg, _petalSidewaysClampDeg);

        float targetLean = (forwardLean + sidewaysLean) * Mathf.Clamp01(speed);
        _petalCurrentLean = Mathf.Lerp(_petalCurrentLean, targetLean, Time.deltaTime * _petalLeanLerpSpeed);
        _petal.localRotation = Quaternion.Euler(0f, 0f, _petalCurrentLean);
    }

    // ── Head bob procedural animation ──────────────────────────────────────────

    private Vector3 _headBaseLocalPos;

    /// <summary>
    /// Finds the Head child of the currently active direction view and applies a
    /// cutesy figure-8 bob: Y follows a sine, X follows cosine (offset by 90°),
    /// and Z-rotation wiggles on a separate sine. All scaled by movement speed.
    /// </summary>
    private void UpdateHeadBob(float speed)
    {
        var head = FindActiveHead();
        if (head == null) return;

        // Cache base position once (direction views all use the same local pos)
        if (_headBaseLocalPos == default)
            _headBaseLocalPos = head.localPosition;

        float t = Time.time * _headBobSpeed;
        float speedFactor = Mathf.Clamp01(speed);

        // Figure-8: Y bounces twice per cycle, X sways once
        float y = Mathf.Sin(t * 2f) * _headBobHeight * speedFactor;
        float x = Mathf.Cos(t) * _headBobSway * speedFactor;
        float zTilt = Mathf.Sin(t) * _headBobTiltDeg * speedFactor;

        head.localPosition = _headBaseLocalPos + new Vector3(x, y, 0f);
        head.localRotation = Quaternion.Euler(0f, 0f, zTilt);
    }

    private Transform FindActiveHead()
    {
        if (_viewFront != null && _viewFront.activeSelf) return _viewFront.transform.Find("Head");
        if (_viewBack != null && _viewBack.activeSelf) return _viewBack.transform.Find("Head");
        if (_viewSide != null && _viewSide.activeSelf) return _viewSide.transform.Find("Head");
        if (_viewLeftBack != null && _viewLeftBack.activeSelf) return _viewLeftBack.transform.Find("Head");
        if (_viewLeftDown != null && _viewLeftDown.activeSelf) return _viewLeftDown.transform.Find("Head");
        return null;
    }

    // ── Limb walk cycle procedural animation ───────────────────────────────────

    /// <summary>
    /// Walk cycle for feet and arms. Left/right feet alternate (180° out of phase).
    /// Arms swing opposite to their same-side foot (right arm forward when left foot forward).
    /// Rotation axis depends on facing: Front/Back use X-axis (swing into screen),
    /// Side/Diagonal use Z-axis (swing sideways). Sprite pivots are already at joints.
    /// </summary>
    private void UpdateLimbs(float speed)
    {
        var view = GetActiveView();
        if (view == null) return;

        float t = Time.time * _limbCycleSpeed;
        float sf = Mathf.Clamp01(speed);

        // Front/Back/Left_Down → X-axis (swing into screen); Side/Left_Back → Z-axis (swing sideways)
        bool useXAxis = (_viewFront != null && _viewFront.activeSelf) ||
                         (_viewBack != null && _viewBack.activeSelf) ||
                         (_viewLeftDown != null && _viewLeftDown.activeSelf);

        // Phase for left foot (also drives right arm — opposite limb)
        float leftPhase  = Mathf.Sin(t);
        // Phase for right foot (also drives left arm — opposite limb)
        float rightPhase = Mathf.Sin(t + Mathf.PI); // 180° offset

        foreach (Transform child in view.transform)
        {
            string n = child.name;
            // Head is driven by UpdateHeadBob — skip here
            if (n == "Head") continue;

            float phase;
            float footTilt;
            float armTilt;

            if (n == "left_foot")
            {
                phase = leftPhase;
                footTilt = -leftPhase * _footTiltDeg * sf;
                child.localRotation = useXAxis
                    ? Quaternion.Euler(footTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, footTilt);
            }
            else if (n == "right_foot")
            {
                phase = rightPhase;
                footTilt = -rightPhase * _footTiltDeg * sf;
                child.localRotation = useXAxis
                    ? Quaternion.Euler(footTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, footTilt);
            }
            else if (n == "right_arm")
            {
                // Right arm swings with left foot (same phase)
                armTilt = leftPhase * _armTiltDeg * sf;
                child.localRotation = useXAxis
                    ? Quaternion.Euler(armTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, armTilt);
            }
            else if (n == "left_arm")
            {
                // Left arm swings with right foot (same phase)
                armTilt = rightPhase * _armTiltDeg * sf;
                child.localRotation = useXAxis
                    ? Quaternion.Euler(armTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, armTilt);
            }
        }
    }

    private GameObject GetActiveView()
    {
        if (_viewFront != null && _viewFront.activeSelf) return _viewFront;
        if (_viewBack != null && _viewBack.activeSelf) return _viewBack;
        if (_viewSide != null && _viewSide.activeSelf) return _viewSide;
        if (_viewLeftBack != null && _viewLeftBack.activeSelf) return _viewLeftBack;
        if (_viewLeftDown != null && _viewLeftDown.activeSelf) return _viewLeftDown;
        return null;
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        _animator = this.GetComponent<Animator>();
        if (_sprite == null && _visualRoot != null) _sprite = _visualRoot.GetComponentInChildren<SpriteRenderer>();
        if (_camera == null) _camera = Camera.main;

        if (_visualRoot != null)
        {
            _visualRoot.localScale = Vector3.one * _visualScale;

            // Auto-find direction views by name if not assigned
            if (_viewFront == null) _viewFront = _visualRoot.Find("Front")?.gameObject;
            if (_viewBack == null) _viewBack = _visualRoot.Find("Back")?.gameObject;
            if (_viewSide == null) _viewSide = _visualRoot.Find("Side")?.gameObject;
            if (_viewLeftBack == null) _viewLeftBack = _visualRoot.Find("Left_Back")?.gameObject;
            if (_viewLeftDown == null) _viewLeftDown = _visualRoot.Find("Left_Down")?.gameObject;
            if (_petal == null) _petal = _visualRoot.Find("petal");
        }

        CacheAttackClipFrames();
    }

    /// <summary>
    /// Record each attack clip's last-frame index (length × frameRate) so the windup can scrub to
    /// exact frames. Clip names come from FlynnAnimationSetup: Flynn_attack_01..04 → tool index 1..4.
    /// </summary>
    private void CacheAttackClipFrames()
    {
        _attackLastFrame.Clear();
        if (_animator == null || _animator.runtimeAnimatorController == null) return;

        foreach (AnimationClip clip in _animator.runtimeAnimatorController.animationClips)
        {
            if (clip == null) continue;
            int idx = clip.name switch
            {
                "Flynn_attack_01" => 1,
                "Flynn_attack_02" => 2,
                "Flynn_attack_03" => 3,
                "Flynn_attack_04" => 4,
                _                 => 0,
            };
            if (idx == 0) continue;
            _attackLastFrame[idx] = Mathf.Max(1f, clip.length * clip.frameRate);
        }
    }

    private void LateUpdate()
    {
        if (_camera == null || _visualRoot == null) return;
        //_visualRoot.rotation = _camera.transform.rotation;
        //_visualRoot.localScale = Vector3.one * _visualScale;
    }

    private void Update()
    {
        // Locomotion is selected by a velocity blend tree: feed the Rigidbody velocity
        // (VelocityX/Y/Z), plus Speed (XZ magnitude) and IsGrounded for the idle/run/air split.
        Vector3 velocity = _controller.MoveInput; // use input for more responsive facing in the blend tree; the Rigidbody velocity feeds the actual speed parameter

        // The blend tree's (0,0) cell is the front/Down pose, so a raw zero input snaps the
        // facing back to front on release. Hold the last pressed XZ direction instead, so the
        // idle pose keeps facing wherever Flynn was last heading. Speed is still the real
        // magnitude, so this only steers the facing cell — it never fakes movement.
        Vector2 xz = new Vector2(velocity.x, velocity.z);
        if (xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone) _lastFacingXZ = xz.normalized;
        Vector2 facingFeed = xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone ? xz : _lastFacingXZ;

        _animator.SetFloat(xVelocityHash, facingFeed.x);
        _animator.SetFloat(yVelocityHash, velocity.y);
        _animator.SetFloat(zVelocityHash, facingFeed.y);
        _animator.SetFloat(SpeedHash, xz.magnitude);
        _animator.SetBool(IsGroundedHash, _controller.IsGrounded);

        // Direction view switching driven from the facing sector (no longer via animation curves).
        UpdateDirectionView(new Vector3(facingFeed.x, velocity.y, facingFeed.y));

        // Procedural petal animation (bounce + lean).
        UpdatePetal(facingFeed, xz.magnitude);

        // Procedural head bob (figure-8 + tilt).
        UpdateHeadBob(xz.magnitude);

        // Procedural limb walk cycle (feet + arms).
        UpdateLimbs(xz.magnitude);

        // While swinging, the swing phase owns animator.speed (freeze on windup, scaled on
        // release) — skip the locomotion playback-speed reset.
        if (_swingPhase == SwingPhase.Charging)
        {
            _animator.speed = 0f;
            return;
        }
        if (_swingPhase == SwingPhase.Releasing)
        {
            _animator.speed = _attackSpeed;
            // Play settles a frame after ReleaseSwing; wait until we see the attack state
            // begin, then hand back to locomotion once it has exited.
            if (IsAttacking) _releaseSeen = true;
            else if (_releaseSeen) _swingPhase = SwingPhase.None;
            return;
        }

        // Blend tree plays at native rate; a prior swing may have left animator.speed scaled.
        _animator.speed = 1f;
    }
}

using UnityEngine;

/// <summary>
/// Drives the procedural cube character rig (twin-stick). Replaces the sprite-sheet
/// <see cref="FlynnAnimationDriver"/> on the cube player while satisfying the same
/// <see cref="IPlayerVisual"/> contract, so wrench/throw/rope/reticle keep working.
///
/// Rig layout (assigned in the Inspector):
///   BodyRig  — yaws to follow the mouse aim point (torso + arms).
///   LegRig   — yaws to the movement direction when moving, blends back to body when idle.
///   FootL/R  — translated in an opposite-phase step cycle along LegRig's local forward.
///   ArmR     — pitched back on charge, swept forward on release (procedural swing pose).
///
/// Decoupling BodyRig (→ mouse) from LegRig (→ move) is what produces the twin-stick look:
/// the torso aims while the legs walk in the direction you actually travel.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class ProceduralCharacterDriver : MonoBehaviour, IPlayerVisual
{
    [Header("Sources")]
    [SerializeField] private SolarpunkCharacterController _controller;

    [Header("Rig")]
    [Tooltip("Torso pivot. Yaws to face the mouse aim point. Holds the body cube + arms.")]
    [SerializeField] private Transform _bodyRig;
    [Tooltip("Leg pivot. Yaws to the movement direction; blends to body facing when idle.")]
    [SerializeField] private Transform _legRig;
    [SerializeField] private Transform _footL;
    [SerializeField] private Transform _footR;
    [Tooltip("Right arm, swept procedurally during a swing.")]
    [SerializeField] private Transform _armR;
    [Tooltip("Hand position used as the throw/rope origin (VisualCenter). Falls back to body centre.")]
    [SerializeField] private Transform _handSocket;

    [Header("Facing")]
    [Tooltip("Rest / idle facing in world space (default -Z = toward the camera / screen-down).")]
    [SerializeField] private Vector3 _restForward = Vector3.back;
    [Tooltip("How far the body turns toward the movement heading off the rest facing. " +
             "1 = face the move direction fully (up = away from camera); " +
             "lower softens it (0.5 → pure left/right leans ~45°). Idle always returns to rest.")]
    [SerializeField, Range(0f, 1f)] private float _leanFactor = 1f;
    [Tooltip("How fast the body/legs slerp toward their target facing (per second).")]
    [SerializeField] private float _turnSpeed = 14f;

    [Header("Step cycle")]
    [Tooltip("Stride length: how far each foot travels fore/aft from neutral (world units).")]
    [SerializeField] private float _stride = 0.12f;
    [Tooltip("Foot lift height at the top of a step (world units).")]
    [SerializeField] private float _stepLift = 0.06f;
    [Tooltip("Step cycles per second at full speed.")]
    [SerializeField] private float _stepFrequency = 2.2f;

    [Header("Visual centre")]
    [Tooltip("Used only when no hand socket is assigned: body-centre height above the root.")]
    [SerializeField] private float _visualHalfHeight = 0.4f;

    [Header("Swing pose")]
    [Tooltip("Arm pitch (deg, local X) at full windup charge.")]
    [SerializeField] private float _windupAngle = -70f;
    [Tooltip("Arm pitch (deg, local X) at the forward end of a swing.")]
    [SerializeField] private float _swingThroughAngle = 60f;
    [Tooltip("Seconds the release sweep takes.")]
    [SerializeField] private float _swingDuration = 0.25f;

    private const float MoveEpsilon = 0.05f;

    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private float _chargePitch;       // current windup pitch while charging
    private float _swingTimer;        // counts down through the release sweep
    private Quaternion _armRest = Quaternion.identity;

    private Vector3 _footLRest;
    private Vector3 _footRRest;
    private float _stepPhase;
    private float _stepWeight;        // 0 idle → 1 moving, smoothed so feet settle

    // ── IPlayerVisual ───────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _handSocket != null ? _handSocket.position
                            : transform.position + Vector3.up * _visualHalfHeight;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking => _swingPhase != SwingPhase.None;

    public void TriggerAttack(int animIndex)
    {
        // No charge: snap straight into a release sweep.
        if (_swingPhase == SwingPhase.None) ReleaseSwing(animIndex, 1f);
    }

    public void BeginChargePose(int animIndex)
    {
        _swingPhase = SwingPhase.Charging;
        _chargePitch = 0f;
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        if (_swingPhase != SwingPhase.Charging) return;
        _chargePitch = Mathf.Lerp(0f, _windupAngle, Mathf.Clamp01(charge01));
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        _swingPhase = SwingPhase.Releasing;
        // Higher animSpeed → shorter sweep (faster follow-through).
        _swingTimer = _swingDuration / Mathf.Max(0.05f, animSpeed);
    }

    public void CancelSwing()
    {
        _swingPhase = SwingPhase.None;
        _swingTimer = 0f;
        _chargePitch = 0f;
    }

    public void FaceWorldDirection(Vector3 worldDir)
    {
        // No-op: facing is fully movement-driven (lean-to-move). Kept for the IPlayerVisual
        // contract — the wrench/rope controllers still call it, but it must not fight the lean.
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private float _restYaw;

    private void Awake()
    {
        if (_controller == null) _controller = GetComponent<SolarpunkCharacterController>();
        Vector3 rest = _restForward; rest.y = 0f;
        if (rest.sqrMagnitude < 0.0001f) rest = Vector3.back;
        _restYaw = Quaternion.LookRotation(rest.normalized, Vector3.up).eulerAngles.y;
        if (_footL != null) _footLRest = _footL.localPosition;
        if (_footR != null) _footRRest = _footR.localPosition;
        if (_armR != null) _armRest = _armR.localRotation;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        UpdateBodyFacing(dt);
        UpdateLegFacing(dt);
        UpdateStepCycle(dt);
        UpdateSwingPose(dt);
    }

    // ── Rig logic ───────────────────────────────────────────────────────────────

    private void UpdateBodyFacing(float dt)
    {
        if (_bodyRig == null) return;

        Vector3 move = _controller.MoveInput;
        move.y = 0f;

        // Turn toward the movement heading in all directions (up = facing away from camera).
        // _leanFactor scales how much of the rest→move angular delta is applied; 1 = face the
        // move direction fully. Idle → rest facing.
        float targetYaw = _restYaw;
        if (move.sqrMagnitude > MoveEpsilon * MoveEpsilon)
        {
            float moveYaw = Quaternion.LookRotation(move.normalized, Vector3.up).eulerAngles.y;
            targetYaw = _restYaw + Mathf.DeltaAngle(_restYaw, moveYaw) * _leanFactor;
        }

        Quaternion target = Quaternion.Euler(0f, targetYaw, 0f);
        _bodyRig.rotation = Quaternion.Slerp(_bodyRig.rotation, target, _turnSpeed * dt);
    }

    private void UpdateLegFacing(float dt)
    {
        // Legs share the body facing; the step cycle runs along that shared forward.
        if (_legRig != null && _bodyRig != null) _legRig.rotation = _bodyRig.rotation;
    }

    private void UpdateStepCycle(float dt)
    {
        float speed01 = Mathf.Clamp01(_controller != null ? _controller.NormalizedSpeed : 0f);
        bool moving = speed01 > 0.05f;

        // Ease the step amplitude in/out so feet settle cleanly when stopping.
        _stepWeight = Mathf.MoveTowards(_stepWeight, moving ? 1f : 0f, dt * 6f);
        if (moving) _stepPhase += dt * _stepFrequency * Mathf.Lerp(0.4f, 1f, speed01) * Mathf.PI * 2f;

        float s = Mathf.Sin(_stepPhase) * _stepWeight;
        ApplyFoot(_footL, _footLRest, s);
        ApplyFoot(_footR, _footRRest, -s);
    }

    private void ApplyFoot(Transform foot, Vector3 rest, float phase)
    {
        if (foot == null) return;
        // phase ∈ [-1,1]: fore/aft along local Z, lift only on the forward (positive) half.
        foot.localPosition = rest
            + Vector3.forward * (phase * _stride)
            + Vector3.up * (Mathf.Max(0f, phase) * _stepLift);
    }

    private void UpdateSwingPose(float dt)
    {
        if (_armR == null) return;

        float pitch;
        switch (_swingPhase)
        {
            case SwingPhase.Charging:
                pitch = _chargePitch;
                break;
            case SwingPhase.Releasing:
                _swingTimer -= dt;
                float t = _swingDuration > 0f
                    ? 1f - Mathf.Clamp01(_swingTimer / (_swingDuration))
                    : 1f;
                // Sweep from the windup angle through to the follow-through angle.
                pitch = Mathf.Lerp(_windupAngle, _swingThroughAngle, t);
                if (_swingTimer <= 0f) _swingPhase = SwingPhase.None;
                break;
            default:
                pitch = 0f;
                break;
        }

        Quaternion target = _armRest * Quaternion.Euler(pitch, 0f, 0f);
        // Snap while actively swinging, ease back to rest when idle.
        _armR.localRotation = _swingPhase == SwingPhase.None
            ? Quaternion.Slerp(_armR.localRotation, target, 12f * dt)
            : target;
    }
}

using UnityEngine;
using Flynn.Events;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private bool wasGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;

/// <summary>
/// Editor utility that creates AnimationClips from sprite PNGs and wires an
/// AnimatorController for Flynn's 2.5D 9-state animation system.
/// Run via menu: Flynn → Setup Animations
/// </summary>
public static class FlynnAnimationSetup
{
    private const string AnimOut = "Assets/Flynn/Animations";
    private const float  Fps     = 12f;
    private const string SpBase  = "Assets/Flynn/Sprites/character_animations";

    // ── Entry point ──────────────────────────────────────────────────────────

    [MenuItem("Flynn/Setup Animations")]
    public static void Run()
    {
        if (!AssetDatabase.IsValidFolder(AnimOut))
            AssetDatabase.CreateFolder("Assets/Flynn", "Animations");

        var clips = BuildAllClips();
        BuildController(clips);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log("[FlynnAnimationSetup] All done.");
    }

    // ── Placeholder diagonal clips (single sprite, decoupled from controller) ──
    //
    // 8-direction support adds FacingDir 3 = back-diagonal (NE/NW). Until real
    // diagonal animations exist, these clips just hold one frame. This menu creates
    // ONLY the clips and leaves Flynn_AnimatorController untouched — wire the
    // FacingDir==3 states/transitions by hand (or extend BuildController later).

    private const string NewCharDir = SpBase + "/New Character";

    // FacingDir → single placeholder sprite (8-direction via flipX for the L/R pair):
    //   0 front, 1 back, 2 side, 3 back-diagonal (NE/NW), 4 front-diagonal (SE/SW).
    private static readonly (string suffix, string sprite)[] PlaceholderDirs =
    {
        ("Front",    "character_front_orth.png"),
        ("Back",     "character_back_orth.png"),
        ("Side",     "character_right.png"),
        ("BackDiag", "character_45_back_orth.png"),
        ("FrontDiag","character_45_orth.png"),
    };

    /// <summary>
    /// Sets every locomotion clip (Idle/Run/Jump × 5 directions) to a SINGLE frame of the
    /// matching New Character sprite. Existing clips are rewritten in place (GUID preserved,
    /// so AnimatorController state references survive); missing ones are created. The
    /// AnimatorController is NOT touched — wire the FacingDir==3/4 diagonal states by hand.
    /// </summary>
    [MenuItem("Flynn/Set Placeholder Sprites (single frame)")]
    public static void SetPlaceholderSprites()
    {
        if (!AssetDatabase.IsValidFolder(AnimOut))
            AssetDatabase.CreateFolder("Assets/Flynn", "Animations");

        int ok = 0, total = 0;
        foreach (var (suffix, spriteFile) in PlaceholderDirs)
        {
            string spritePath = $"{NewCharDir}/{spriteFile}";
            foreach (var (prefix, loop) in new[] { ("Idle", true), ("Run", true), ("Jump", false) })
            {
                total++;
                if (SetSingleSpriteClip($"Flynn_{prefix}_{suffix}", spritePath, loop) != null) ok++;
            }
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"[FlynnAnimationSetup] Placeholder sprites set: {ok}/{total} clips. " +
                  "Controller untouched — wire FacingDir==3 (back-diag) & ==4 (front-diag) states manually.");
    }

    /// <summary>
    /// Forces a clip to a one-frame sprite animation. Loads the existing asset (preserving its
    /// GUID + controller references) or creates it if absent, then overwrites the m_Sprite curve.
    /// </summary>
    private static AnimationClip SetSingleSpriteClip(string clipName, string spritePath, bool loop)
    {
        var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
        if (sprite == null)
        {
            Debug.LogWarning($"[FlynnAnimationSetup] Sprite not found (imported as a Sprite?): {spritePath}");
            return null;
        }

        string outPath = $"{AnimOut}/{clipName}.anim";
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath);
        bool existed = clip != null;
        if (!existed) clip = new AnimationClip();
        clip.frameRate = Fps;

        var binding = new EditorCurveBinding
        {
            type         = typeof(SpriteRenderer),
            path         = "",
            propertyName = "m_Sprite"
        };
        // Single keyframe replaces any prior multi-frame curve for this binding.
        var keys = new[] { new ObjectReferenceKeyframe { time = 0f, value = sprite } };
        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        if (!existed) AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);

        Debug.Log($"[FlynnAnimationSetup] {(existed ? "Rewrote" : "Created")} '{clipName}' → {sprite.name} (1 frame, loop={loop}).");
        return clip;
    }

    // ── Clip creation ────────────────────────────────────────────────────────

    private static Dictionary<string, AnimationClip> BuildAllClips()
    {
        // (clipName, folder, looping)
        var defs = new (string name, string folder, bool loop)[]
        {
            ("Flynn_Idle_Front",  SpBase + "/positive/idel_02", true),
            ("Flynn_Run_Front",   SpBase + "/positive/run_01",  true),
            ("Flynn_Jump_Front",  SpBase + "/positive/jump_02", false),
            ("Flynn_Idle_Back",   SpBase + "/back/idel_01",     true),
            ("Flynn_Run_Back",    SpBase + "/back/run_01",      true),
            ("Flynn_Jump_Back",   SpBase + "/back/jump_01",     false),
            ("Flynn_Idle_Side",   SpBase + "/side/idel_03",     true),
            ("Flynn_Run_Side",    SpBase + "/side/run_03",      true),
            ("Flynn_Jump_Side",   SpBase + "/side/jump_03",     false),
            // ── Attack animations (one-shot, tool-specific) ──────────────
            ("Flynn_attack_01",   SpBase + "/attack_01",        false),  // pick
            ("Flynn_attack_02",   SpBase + "/attack_02",        false),  // axe
            ("Flynn_attack_03",   SpBase + "/attack_03",        false),  // hammer
            ("Flynn_attack_04",   SpBase + "/attack_04",        false),  // wrench
        };

        var map = new Dictionary<string, AnimationClip>();
        foreach (var d in defs)
        {
            var clip = MakeClip(d.name, d.folder, d.loop);
            if (clip != null) map[d.name] = clip;
        }
        return map;
    }

    private static AnimationClip MakeClip(string clipName, string folder, bool loop)
    {
        // Convert asset-relative folder to filesystem path
        string dataPath = Application.dataPath.Replace('\\', '/'); // ends with /Assets
        string sysDir   = dataPath + "/" + folder.Substring("Assets/".Length);

        if (!Directory.Exists(sysDir))
        {
            Debug.LogWarning($"[FlynnAnimationSetup] Folder not found: {sysDir}");
            return null;
        }

        var pngPaths = Directory.GetFiles(sysDir, "*.png")
                                .Select(p => p.Replace('\\', '/'))
                                .OrderBy(Path.GetFileName)
                                .ToArray();

        var sprites = new List<Sprite>(pngPaths.Length);
        foreach (var full in pngPaths)
        {
            string assetPath = "Assets/" + full.Substring(dataPath.Length + 1);
            var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(assetPath);
            if (sprite != null)
                sprites.Add(sprite);
            else
                Debug.LogWarning($"[FlynnAnimationSetup] Sprite not found at: {assetPath}");
        }

        if (sprites.Count == 0)
        {
            Debug.LogWarning($"[FlynnAnimationSetup] No sprites loaded for clip '{clipName}'");
            return null;
        }

        var clip = new AnimationClip { frameRate = Fps };

        var binding = new EditorCurveBinding
        {
            type         = typeof(SpriteRenderer),
            path         = "",
            propertyName = "m_Sprite"
        };

        var keys = new ObjectReferenceKeyframe[sprites.Count];
        for (int i = 0; i < sprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / Fps, value = sprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        // Loop settings
        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        // Save asset (replace if already exists)
        string outPath = $"{AnimOut}/{clipName}.anim";
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);

        Debug.Log($"[FlynnAnimationSetup] Created '{clipName}'  ({sprites.Count} frames, loop={loop})");
        return clip;
    }

    // ── AnimatorController creation ──────────────────────────────────────────

    private static void BuildController(Dictionary<string, AnimationClip> clips)
    {
        string ctrlPath = $"{AnimOut}/Flynn_AnimatorController.controller";
        if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ctrlPath) != null)
            AssetDatabase.DeleteAsset(ctrlPath);

        var ctrl = AnimatorController.CreateAnimatorControllerAtPath(ctrlPath);
        ctrl.AddParameter("Speed",       AnimatorControllerParameterType.Float);
        ctrl.AddParameter("IsGrounded",  AnimatorControllerParameterType.Bool);
        ctrl.AddParameter("FacingDir",   AnimatorControllerParameterType.Int);
        ctrl.AddParameter("Attack",      AnimatorControllerParameterType.Trigger);
        ctrl.AddParameter("AttackIndex", AnimatorControllerParameterType.Int);

        var sm = ctrl.layers[0].stateMachine;

        // Create states
        var idleFront = AddState(sm, clips, "Idle_Front", "Flynn_Idle_Front", new Vector3(300,    0, 0));
        var runFront  = AddState(sm, clips, "Run_Front",  "Flynn_Run_Front",  new Vector3(600,    0, 0));
        var jumpFront = AddState(sm, clips, "Jump_Front", "Flynn_Jump_Front", new Vector3(900,    0, 0));
        var idleBack  = AddState(sm, clips, "Idle_Back",  "Flynn_Idle_Back",  new Vector3(300, -200, 0));
        var runBack   = AddState(sm, clips, "Run_Back",   "Flynn_Run_Back",   new Vector3(600, -200, 0));
        var jumpBack  = AddState(sm, clips, "Jump_Back",  "Flynn_Jump_Back",  new Vector3(900, -200, 0));
        var idleSide  = AddState(sm, clips, "Idle_Side",  "Flynn_Idle_Side",  new Vector3(300,  200, 0));
        var runSide   = AddState(sm, clips, "Run_Side",   "Flynn_Run_Side",   new Vector3(600,  200, 0));
        var jumpSide  = AddState(sm, clips, "Jump_Side",  "Flynn_Jump_Side",  new Vector3(900,  200, 0));

        sm.defaultState = idleFront;

        AnimatorStateTransition t;

        // ── From Idle_Front ──────────────────────────────────────────────────
        t = MkTrans(idleFront, runFront);
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  0f,   "FacingDir");

        t = MkTrans(idleFront, jumpFront);
        t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Equals, 0f, "FacingDir");

        t = MkTrans(idleFront, idleBack);
        t.AddCondition(AnimatorConditionMode.Equals, 1f, "FacingDir");

        t = MkTrans(idleFront, idleSide);
        t.AddCondition(AnimatorConditionMode.Equals, 2f, "FacingDir");

        // ── From Run_Front ───────────────────────────────────────────────────
        t = MkTrans(runFront, idleFront);
        t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

        t = MkTrans(runFront, idleFront);
        t.AddCondition(AnimatorConditionMode.NotEqual, 0f, "FacingDir");

        t = MkTrans(runFront, jumpFront);
        t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");

        // ── From Jump_Front ──────────────────────────────────────────────────
        t = MkTrans(jumpFront, idleFront);
        t.AddCondition(AnimatorConditionMode.If,     0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Less,   0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals, 0f,   "FacingDir");

        t = MkTrans(jumpFront, runFront);
        t.AddCondition(AnimatorConditionMode.If,      0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  0f,   "FacingDir");

        // ── From Idle_Back ───────────────────────────────────────────────────
        t = MkTrans(idleBack, runBack);
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  1f,   "FacingDir");

        t = MkTrans(idleBack, jumpBack);
        t.AddCondition(AnimatorConditionMode.IfNot,  0f, "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Equals, 1f, "FacingDir");

        t = MkTrans(idleBack, idleFront);
        t.AddCondition(AnimatorConditionMode.Equals, 0f, "FacingDir");

        t = MkTrans(idleBack, idleSide);
        t.AddCondition(AnimatorConditionMode.Equals, 2f, "FacingDir");

        // ── From Run_Back ────────────────────────────────────────────────────
        t = MkTrans(runBack, idleBack);
        t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

        t = MkTrans(runBack, idleBack);
        t.AddCondition(AnimatorConditionMode.NotEqual, 1f, "FacingDir");

        t = MkTrans(runBack, jumpBack);
        t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");

        // ── From Jump_Back ───────────────────────────────────────────────────
        t = MkTrans(jumpBack, idleBack);
        t.AddCondition(AnimatorConditionMode.If,     0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Less,   0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals, 1f,   "FacingDir");

        t = MkTrans(jumpBack, runBack);
        t.AddCondition(AnimatorConditionMode.If,      0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  1f,   "FacingDir");

        // ── From Idle_Side ───────────────────────────────────────────────────
        t = MkTrans(idleSide, runSide);
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  2f,   "FacingDir");

        t = MkTrans(idleSide, jumpSide);
        t.AddCondition(AnimatorConditionMode.IfNot,  0f, "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Equals, 2f, "FacingDir");

        t = MkTrans(idleSide, idleFront);
        t.AddCondition(AnimatorConditionMode.Equals, 0f, "FacingDir");

        t = MkTrans(idleSide, idleBack);
        t.AddCondition(AnimatorConditionMode.Equals, 1f, "FacingDir");

        // ── From Run_Side ────────────────────────────────────────────────────
        t = MkTrans(runSide, idleSide);
        t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

        t = MkTrans(runSide, idleSide);
        t.AddCondition(AnimatorConditionMode.NotEqual, 2f, "FacingDir");

        t = MkTrans(runSide, jumpSide);
        t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");

        // ── From Jump_Side ───────────────────────────────────────────────────
        t = MkTrans(jumpSide, idleSide);
        t.AddCondition(AnimatorConditionMode.If,     0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Less,   0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals, 2f,   "FacingDir");

        t = MkTrans(jumpSide, runSide);
        t.AddCondition(AnimatorConditionMode.If,      0f,   "IsGrounded");
        t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        t.AddCondition(AnimatorConditionMode.Equals,  2f,   "FacingDir");

        // ── Attack states (AnyState → Attack_N, then → Idle_Front on exit) ─────────────
        var attackDefs = new (string state, string clip, int index)[]{
            ("Attack_Pick",   "Flynn_attack_01", 1),
            ("Attack_Axe",    "Flynn_attack_02", 2),
            ("Attack_Hammer", "Flynn_attack_03", 3),
            ("Attack_Wrench", "Flynn_attack_04", 4),
        };

        for (int ai = 0; ai < attackDefs.Length; ai++)
        {
            var (stateName, clipName, animIndex) = attackDefs[ai];
            var attackState = AddState(sm, clips, stateName, clipName,
                                       new Vector3(300 + ai * 300, -500, 0));
            // Tag so FlynnAnimationDriver.IsAttacking can detect the attack state (its
            // double-fire guard and the swing release→idle handoff both depend on this).
            attackState.tag = "Attack";

            // AnyState → attack: trigger fired AND AttackIndex matches
            var anyTrans = sm.AddAnyStateTransition(attackState);
            anyTrans.hasExitTime       = false;
            anyTrans.duration          = 0f;
            anyTrans.canTransitionToSelf = false;
            anyTrans.AddCondition(AnimatorConditionMode.If,     0f,          "Attack");
            anyTrans.AddCondition(AnimatorConditionMode.Equals, animIndex,   "AttackIndex");

            // Attack → Idle_Front once the clip has mostly played (85% through)
            var exitTrans = attackState.AddTransition(idleFront);
            exitTrans.hasExitTime = true;
            exitTrans.exitTime    = 0.85f;
            exitTrans.duration    = 0f;
        }

        EditorUtility.SetDirty(ctrl);
        Debug.Log("[FlynnAnimationSetup] AnimatorController created.");
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    private static AnimatorState AddState(
        AnimatorStateMachine sm,
        Dictionary<string, AnimationClip> clips,
        string stateName,
        string clipName,
        Vector3 position)
    {
        var state = sm.AddState(stateName, position);
        if (clips.TryGetValue(clipName, out var clip))
            state.motion = clip;
        return state;
    }

    private static AnimatorStateTransition MkTrans(AnimatorState from, AnimatorState to)
    {
        var t = from.AddTransition(to);
        t.hasExitTime = false;
        t.duration    = 0f;
        t.exitTime    = 0f;
        return t;
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

