    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
